=== Stay.java
     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	/** What a rate plan needs to know to price and validate a reservation. */
     8	public record Stay(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
     9	    public int nights() {
    10	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    11	    }
    12	
    13	    /** Sum of the nightly prices, seasonality included. */
    14	    public BigDecimal nightsTotal() {
    15	        BigDecimal sum = Money.ZERO;
    16	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    17	            sum = sum.add(Season.nightPrice(room, night));
    18	        }
    19	        return sum;
    20	    }
    21	}
