     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Season {
     8	    private Season() {}
     9	
    10	    public static boolean isHigh(LocalDate night) {
    11	        Month month = night.getMonth();
    12	        return month == Month.JULY || month == Month.JANUARY || month == Month.FEBRUARY
    13	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    14	    }
    15	
    16	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    17	        return isHigh(night) ? Money.fraction(room.nightlyRate(), "1.20") : room.nightlyRate();
    18	    }
    19	}
