     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	public final class Money {
    10	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    11	
    12	    private Money() {}
    13	
    14	    public static BigDecimal round(BigDecimal value) {
    15	        return value.setScale(2, RoundingMode.HALF_EVEN);
    16	    }
    17	
    18	    public static BigDecimal of(String value) {
    19	        return round(new BigDecimal(value));
    20	    }
    21	
    22	    /** Fraction of an amount (e.g. 0.15 of 100.00), rounded to cents. */
    23	    public static BigDecimal fraction(BigDecimal amount, String fraction) {
    24	        return round(amount.multiply(new BigDecimal(fraction)));
    25	    }
    26	
    27	    /** Brazilian format: R$ 1.234,56 */
    28	    public static String format(BigDecimal value) {
    29	        DecimalFormat format = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.of("pt", "BR")));
    30	        return "R$ " + format.format(value);
    31	    }
    32	}
=== Hotel.java
     1	package pousada;
     2	
     3	import pousada.plan.RatePlan;
     4	
     5	import java.time.LocalDate;
     6	import java.util.ArrayList;
     7	import java.util.List;
     8	
     9	/** Rooms, reservations and the operations the reception and the site perform on them. */
    10	public class Hotel {
    11	    private final List<Room> rooms = List.of(
    12	            new Room(101, RoomType.STANDARD), new Room(102, RoomType.STANDARD),
    13	            new Room(201, RoomType.DELUXE), new Room(202, RoomType.DELUXE),
    14	            new Room(301, RoomType.SUITE));
    15	    private final List<Reservation> reservations = new ArrayList<>();
    16	    private final Outbox outbox;
    17	
    18	    public Hotel(Outbox outbox) {
    19	        this.outbox = outbox;
    20	    }
    21	
    22	    public List<Room> rooms() { return rooms; }
    23	
    24	    public synchronized List<Reservation> reservations() { return List.copyOf(reservations); }
    25	
    26	    public Outbox outbox() { return outbox; }
    27	
    28	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    29	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan,
    30	                                           String companyCode) {
    31	        Room room = rooms.stream().filter(r -> r.number() == roomNumber).findFirst()
    32	                .orElseThrow(() -> new PousadaException(ErrorCode.ROOM_NOT_FOUND, "Quarto " + roomNumber + " não existe"));
    33	        if (guests > room.capacity()) {
    34	            throw new PousadaException(ErrorCode.CAPACITY_EXCEEDED,
    35	                    "O quarto " + roomNumber + " comporta no máximo " + room.capacity() + " hóspedes");
    36	        }
    37	        Stay stay = new Stay(room, checkIn, checkOut, companyCode);
    38	        plan.validate(stay);
    39	        boolean taken = reservations.stream().anyMatch(r -> r.room.equals(room)
    40	                && r.status() != ReservationStatus.CANCELLED && r.overlaps(checkIn, checkOut));
    41	        if (taken) {
    42	            throw new PousadaException(ErrorCode.ROOM_UNAVAILABLE, "Quarto já reservado em alguma das noites");
    43	        }
    44	        Reservation reservation = new Reservation(reservations.size() + 1, room, guestName, guestEmail, guestCpf,
    45	                checkIn, checkOut, guests, plan, plan.quote(stay));
    46	        reservations.add(reservation);
    47	        return reservation;
    48	    }
    49	
    50	    public synchronized Reservation find(String id) {
    51	        try {
    52	            int index = Integer.parseInt(id);
    53	            if (index >= 1 && index <= reservations.size()) return reservations.get(index - 1);
    54	        } catch (NumberFormatException ignored) {
    55	            // falls through to not found
    56	        }
    57	        throw new PousadaException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva " + id + " não existe");
    58	    }
    59	
    60	    public synchronized Reservation confirm(String id) {
    61	        Reservation r = find(id);
    62	        r.confirm();
    63	        outbox.sendEmail(r.guestEmail, "Reserva confirmada - Pousada Maré Alta",
    64	                "Olá, " + r.guestName + "!\n\n"
    65	                        + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    66	                        + Receipt.of(r).text() + "\n\n"
    67	                        + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    68	                        + "Até breve!");
    69	        return r;
    70	    }
    71	
    72	    public synchronized Reservation cancel(String id) {
    73	        Reservation r = find(id);
    74	        r.cancel();
    75	        return r;
    76	    }
    77	
    78	    public synchronized Reservation checkIn(String id) {
    79	        Reservation r = find(id);
    80	        r.checkIn();
    81	        return r;
    82	    }
    83	
    84	    public synchronized Receipt checkOut(String id) {
    85	        Reservation r = find(id);
    86	        r.checkOut();
    87	        return Receipt.of(r);
    88	    }
    89	
    90	    public synchronized Receipt document(String id) {
    91	        Reservation r = find(id);
    92	        if (!r.status().isPaid()) {
    93	            throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    94	                    "A segunda via só existe para reserva paga");
    95	        }
    96	        return Receipt.of(r);
    97	    }
    98	}
=== Reservation.java
     1	package pousada;
     2	
     3	import pousada.plan.RatePlan;
     4	
     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	
     8	import static pousada.ReservationStatus.*;
     9	
    10	public class Reservation {
    11	    public final int id;
    12	    public final Room room;
    13	    public final String guestName, guestEmail, guestCpf;
    14	    public final LocalDate checkIn, checkOut;
    15	    public final int guests;
    16	    public final RatePlan plan;
    17	    public final Quote quote;
    18	    private ReservationStatus status = PENDING;
    19	    private BigDecimal amountPaid = Money.ZERO;
    20	    private BigDecimal refund;
    21	
    22	    public Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf,
    23	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan, Quote quote) {
    24	        this.id = id;
    25	        this.room = room;
    26	        this.guestName = guestName;
    27	        this.guestEmail = guestEmail;
    28	        this.guestCpf = guestCpf;
    29	        this.checkIn = checkIn;
    30	        this.checkOut = checkOut;
    31	        this.guests = guests;
    32	        this.plan = plan;
    33	        this.quote = quote;
    34	    }
    35	
    36	    public ReservationStatus status() { return status; }
    37	    public BigDecimal amountPaid() { return amountPaid; }
    38	    public BigDecimal refund() { return refund; }
    39	
    40	    public BigDecimal netAmount() {
    41	        return Money.round(amountPaid.subtract(refund == null ? BigDecimal.ZERO : refund));
    42	    }
    43	
    44	    public boolean overlaps(LocalDate otherIn, LocalDate otherOut) {
    45	        return checkIn.isBefore(otherOut) && otherIn.isBefore(checkOut);
    46	    }
    47	
    48	    public void confirm() {
    49	        require("confirmar", PENDING);
    50	        status = CONFIRMED;
    51	        amountPaid = quote.total();
    52	    }
    53	
    54	    public void checkIn() {
    55	        require("fazer check-in de", CONFIRMED);
    56	        status = CHECKED_IN;
    57	    }
    58	
    59	    public void checkOut() {
    60	        require("fazer check-out de", CHECKED_IN);
    61	        status = CHECKED_OUT;
    62	    }
    63	
    64	    public void cancel() {
    65	        require("cancelar", PENDING, CONFIRMED);
    66	        refund = plan.refund(amountPaid);
    67	        status = CANCELLED;
    68	    }
    69	
    70	    private void require(String action, ReservationStatus... allowed) {
    71	        for (ReservationStatus s : allowed) {
    72	            if (s == status) return;
    73	        }
    74	        throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    75	                "Não é possível " + action + " uma reserva com situação " + status);
    76	    }
    77	}
